/// <summary>
/// This method serves as example how to build your own query from code. This method builds
/// not only query, but also guidlines for default XML document layout (by adding defaut fields, and Layout options on datasource)
/// </summary>
/// <returns></returns>
[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')] // value _DO_NOT_SHOW_ indicates framework, that this method is not 'value' method, and should
// be shown in lookups for value expressions
public Query queryBuild()
{
    Query                queryLocal = new Query();
    // At this example, we will build CustTable query
    // While building query, no parameters and related sources exist
    // specify ranges after report_runInit() is executed
    QueryBuildDataSource qbds;
    // add data source

    qbds = queryLocal.addDataSource(tableNum(CustTable));    // Add datasource
    qbds.name(tableStr(CustTable)); // Data source name will be used as report data source name, so to avoid names like CustTable_1, we set
    // name the same as table name.
    // add fields
    // It's mandatory to add fields with queryBuildAddField() because it serves as source for loading default report elements
    this.queryBuildAddField(qbds, fieldStr(CustTable, AccountNum));
    // or method
    this.queryBuildAddMethod(qbds, tableMethodStr(CustTable, NameAlias));


    /*
    // Adding another datasource
    qbds2 = qbds.addDataSource(tableNum(MyTable2));
    qbds2.name(tableStr(MyTable2)); // Specify meaningfull name for data source
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One); // Always use 1:1 fetch
    qbds2.relations(true);

    // and field
    this.queryBuildAddField(qbds2, fieldStr(MyTable2, NumberOf));

    // !!!! Do not forget this when adding more data sources:
    // Specifying layout property (both tables will be shown in the same xml path depth)
    this.queryBuildAddLayout(queryLocal, qbds2, LACQueryDSLayout::SameLevel);
    */

    return queryLocal;
}

[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')]
public void report_runInit()
{
    QueryBuildDataSource qbds;
    CustAccount          custAccount;
    LACReportRun_Query   rrLocal;
    Query queryLocal;

    super();

    // Parameter map contain values from report dialog fields, and contains both value in original type and value as strin
    custAccount = this.getParameter('AccountNum'); // lookup always returs Str value
    // this.parametersMap().lookupOrig("TransDate") <- this would return Date, if TransDate was a date control

    rrLocal = this.parmReportRun();
    queryLocal = rrLocal.queryService().queryRun().query(); // Retrieving Query from run time service
    qbds = queryLocal.dataSourceTable(tableNum(CustTable));
    SysQuery::findOrCreateRange(qbds, fieldNum(CustTable, AccountNum)).value(custAccount); // Manually setting query range
    //SysQuery::findOrCreateRange(qbds, fieldNum(CustTrans, TransDate)).value(queryValue(this.parametersMap().lookupOrig("TransDate"))); // Manually setting query range
}

/// <summary>
///     This method demonstrates available printer settings to control report and report print settings dialog execution
/// </summary>
public static void Lasernet_Specific_PrinterSettings()
{
    // =================================== Lasernet specific printer destination settings ================================================================
    SRSPrintDestinationSettings destinationSettings = new SRSPrintDestinationSettings(); // Creating print destination object
    destinationSettings.printMediumType(SRSPrintMediumType::LACPredefined); // Specifying that destination must be Lasernet (another option LACScreen)
    // Configuring Lasernet specific properties
    LACDestinationSettings lacDestinationSettings = destinationSettings.lacDestinationSettings();

    //  ==== Report Delivery settings ====

    lacDestinationSettings.destTypes4Print(LACDestTypes4Print::UsePredefinedDest); // Indicates that report should be executed to predefined destination
    lacDestinationSettings.defaultDestTypes4Print(LACDestTypes4DefaultPrint::None); // Indicates that if no predefined destination meets criteria, no fall back destination should be used
    // if fall back destination is used, - use regular methods for fall back destination specification:
    // Example: if fall back destination is LACDestTypes4DefaultPrint::Email then fall back email is specified
    // lacDestinationSettings.emailTo('fallbackemail@company.com'); and etc.
    lacDestinationSettings.skipDestinations(NoYes::Yes); // This would mean that no report destination processing will be performed, report will still be archived, but if used without
    // returnFileData(true) it will not be processed in Lasernet. (basically only XML file will be archived without PDF processing)
    lacDestinationSettings.skipDelivery(NoYes::Yes); // Instructs report rendering process to skip file saving in storage.
    // Normally this can be used in connection to returnFileData(true) to force synchronous file processing.
    lacDestinationSettings.returnFileData(NoYes::Yes); // Indicates to process report file synchronously, and read file data into LACResultSet provided by
    // SRSReportExecutionInfo object

    //  ==== Various permissions for report print settings dialog ====

    lacDestinationSettings.allowCustomProperties(NoYes::Yes);    // Indicates that custom properties button is shown on printer settings dialog, allowing specification
    // of custom properties on Report printer settings dialog directly
    lacDestinationSettings.allowForcedReRun(NoYes::Yes);         // indicator if report should be fully reprocessed (true), or if it is already in Lasernet archive, no reprocessing is required) (false)
    lacDestinationSettings.allowLanguageEnforce(NoYes::Yes);     // Indicator to show language Id field on dialog, that can overwrite default report language
    lacDestinationSettings.allowManualArchive(NoYes::Yes);       // Indicator to show "Save report to archive?" check box in printer settings dialog. if not set - automatic configuration used from report
    lacDestinationSettings.allowManualDocuRef(NoYes::Yes);       // Enables modification of attachment rules for report execution, by showing controls for report attachments in printer settings dialog
    lacDestinationSettings.allowManualOverlay(NoYes::Yes);       // Enables modification of overlay directly in printer settings dialog
    lacDestinationSettings.allowManualPreviewFormat(NoYes::Yes); // Enables dialog field for specification of report preview format
    lacDestinationSettings.disableUserDefined(NoYes::Yes);       // Removes UsePredefinedDestionation and CustomPort from available Lasernet destination settings on dialog
    lacDestinationSettings.forceEnabled(NoYes::Yes);             // Lasernet settings are normally shown only if report is found and configured for lasernet. This property enforces that Lasernet
    // destination settings are always shown in dialog regardless of report (for example reportName is not available at the time,
    // report is not activated, or generic settings are specified)
    lacDestinationSettings.onlyLaserNetDestinations(NoYes::Yes); // Indicator to show only lasernet destination in printer settings dialog. All standard SSRS destinations will be hidden
    // Normally this should be used with all query-based reports
    lacDestinationSettings.manualArchive(NoYes::Yes);            // Manual indicator is report should be archived. This is overwriting settings on report, and can be used with allowManualArchive(NoYes::Yes)
    lacDestinationSettings.manualDocuRefType(LACManualOverwriteType::Disabled); // Manual indicator to force attachments on report to be disabled, overwritten and etc
    lacDestinationSettings.manualLanguageId('en-us');            // Manual value to overwrite report language
    lacDestinationSettings.manualOverlayType(LACManualOverwriteType::Disabled); // Manual indicator to overwrite/disable append overlay to report
    lacDestinationSettings.manualPreviewFormat('.DOC');         // Manual indicator for preview format. This value should be present in LACFileFormats table.
}

/// <summary>
///   Constructor method, initializing instance of the class
/// </summary>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_Code construct()
{
    return new LACTutorialCustomCode_Code();
}

/// <summary>
///   Unpacks class instance. Required method, allowing to cache the custom code for the report execution
/// </summary>
/// <param name = "packedClass">Packed class instance</param>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_Code Create(container packedClass)
{
    LACTutorialCustomCode_Code valueSource = LACTutorialCustomCode_Code::construct();
    valueSource.unpack(packedClass);
    return valueSource;
}
